#!/usr/bin/env node
/** Build the algorithm reader from content/algorithms.json.
 *
 *  The JSON file is the single source of truth for the thirteen routines:
 *  order, grouping, titles, prose, source paths and tests. This script
 *  validates it and writes two files that consumers import directly:
 *
 *    assets/js/lib/algorithm-guide.js       ES module for the site
 *    lib/python/percolation_atlas/algorithm_index.json
 *
 *  Run with --check to compare the generated files with what is on disk.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const DATA = path.join(ROOT, 'content/algorithms.json');
const JS_OUT = path.join(ROOT, 'assets/js/lib/algorithm-guide.js');
const PY_OUT = path.join(ROOT, 'lib/python/percolation_atlas/algorithm_index.json');
const LANGS = ['en', 'zh', 'de'];
const CHECK = process.argv.includes('--check');

const data = JSON.parse(fs.readFileSync(DATA, 'utf8'));
const problems = [];

function fail(message) {
  problems.push(message);
}

if (data.version !== 1) fail('algorithms.json: version must be 1');
if (!Array.isArray(data.order) || data.order.length === 0) fail('algorithms.json: order is empty');
if (new Set(data.order).size !== data.order.length) fail('algorithms.json: duplicate id in order');

const grouped = [];
for (const group of data.groups || []) {
  if (!group.id || !Array.isArray(group.ids)) fail('algorithms.json: malformed group');
  grouped.push(...group.ids);
}
if (grouped.length !== data.order.length || data.order.some((id) => !grouped.includes(id))) {
  fail('algorithms.json: groups do not cover order exactly');
}

for (const id of data.order) {
  const entry = data.entries[id];
  if (!entry) {
    fail(`${id}: missing entry`);
    continue;
  }
  for (const lang of LANGS) {
    if (!entry.tag?.[lang]) fail(`${id}: missing tag.${lang}`);
    if (!entry.summary?.[lang]) fail(`${id}: missing summary.${lang}`);
    if (!entry.title?.[lang]) fail(`${id}: missing title.${lang}`);
    for (const field of ['purpose', 'steps', 'complexity', 'notes', 'pitfalls']) {
      const value = entry[field]?.[lang];
      if (!Array.isArray(value) || value.length === 0) fail(`${id}: missing ${field}.${lang}`);
    }
    if (!entry.invariant?.[lang]) fail(`${id}: missing invariant.${lang}`);
  }
  if (!Array.isArray(entry.code) || entry.code.length === 0) fail(`${id}: no code paths`);
  for (const item of entry.code || []) {
    if (!item.path || !item.label) fail(`${id}: malformed code entry`);
    else if (!fs.existsSync(path.join(ROOT, item.path))) fail(`${id}: code path missing: ${item.path}`);
  }
  if (!Array.isArray(entry.tests) || entry.tests.length === 0) fail(`${id}: no tests`);
  for (const test of entry.tests || []) {
    if (!fs.existsSync(path.join(ROOT, test))) fail(`${id}: test path missing: ${test}`);
    if (test.endsWith('.js') && !test.startsWith('tests/js/')) fail(`${id}: JS test outside tests/js: ${test}`);
  }
  if (entry.implementations !== entry.code.length) {
    fail(`${id}: implementations=${entry.implementations} but ${entry.code.length} code paths`);
  }
}

if (problems.length) {
  for (const problem of problems) console.error(`FAIL ${problem}`);
  process.exit(1);
}

const js = `/** Generated from content/algorithms.json by scripts/build_algorithms.mjs.
 *  Edit the JSON, then run \`make algorithms\`; do not edit this file by hand. */

export const ALGORITHM_ORDER = ${JSON.stringify(data.order, null, 2)};

export const ALGORITHM_GROUPS = ${JSON.stringify(data.groups, null, 2)};

export const ALGORITHM_GUIDE = ${JSON.stringify(data.entries, null, 2)};

export function guideFor(id, lang) {
  const entry = ALGORITHM_GUIDE[id];
  if (!entry) return null;
  const pick = (field) => entry[field] && (entry[field][lang] || entry[field].en);
  return {
    id,
    tag: entry.tag[lang] || entry.tag.en,
    title: entry.title[lang] || entry.title.en,
    summary: pick('summary') || '',
    purpose: pick('purpose') || [],
    steps: pick('steps') || [],
    invariant: pick('invariant') || '',
    complexity: pick('complexity') || [],
    notes: pick('notes') || [],
    pitfalls: pick('pitfalls') || [],
    code: entry.code,
    tests: entry.tests,
    implementations: entry.implementations,
  };
}
`;

const meta = {
  version: data.version,
  order: data.order,
  groups: data.groups,
  entries: Object.fromEntries(
    data.order.map((id) => {
      const entry = data.entries[id];
      return [id, {
        title: entry.title,
        tag: entry.tag,
        summary: entry.summary,
        doc_title: entry.doc_title,
        complexity: entry.complexity,
        implementations: entry.implementations,
        code: entry.code,
        tests: entry.tests,
      }];
    })
  ),
};
const py = JSON.stringify(meta, null, 1) + '\n';

if (CHECK) {
  const jsNow = fs.existsSync(JS_OUT) ? fs.readFileSync(JS_OUT, 'utf8') : '';
  const pyNow = fs.existsSync(PY_OUT) ? fs.readFileSync(PY_OUT, 'utf8') : '';
  if (jsNow !== js) fail(`${path.relative(ROOT, JS_OUT)} is stale; run make algorithms`);
  if (pyNow !== py) fail(`${path.relative(ROOT, PY_OUT)} is stale; run make algorithms`);
  if (problems.length) {
    for (const problem of problems) console.error(`FAIL ${problem}`);
    process.exit(1);
  }
  console.log(`ok   algorithms: ${data.order.length} entries, generated files up to date`);
  process.exit(0);
}

fs.writeFileSync(JS_OUT, js);
fs.writeFileSync(PY_OUT, py);
console.log(`algorithms: ${data.order.length} entries -> ${path.relative(ROOT, JS_OUT)} and ${path.relative(ROOT, PY_OUT)}`);
